// 在任何first-match读取前完整拒重名；有界深度避免损坏递归吞尽栈。
void unique(const V& value,Integer depth=0){if(depth>64)boundary::fail("TacticLessonJSONTooDeep","");if(const auto* object=value.as<V::Dict>()){std::set<StableId> keys;for(const auto& row:*object){if(!keys.insert(row.first).second)boundary::fail("DuplicateTacticLessonField",row.first);unique(row.second,depth+1);}}else if(const auto* array=value.as<V::Array>())for(const auto& item:*array)unique(item,depth+1);}
WorldId world(const StableId& value){if(value.size()!=32)boundary::fail("InvalidWorldId","");auto digit=[](char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:-1;};WorldId out{};for(std::size_t i=0;i<out.size();++i){auto a=digit(value[2*i]),b=digit(value[2*i+1]);if(a<0||b<0)boundary::fail("InvalidWorldId","");out[i]=static_cast<std::uint8_t>(a*16+b);}return out;}
Status visit_world(CodecVisitor& c,WorldId& value){std::vector<Integer> bytes;for(auto b:value)bytes.push_back(b);c.sequence("world_id",bytes,[](CodecVisitor& q,Integer& b){return q.field("byte",b);});if(c.reading()&&c.status().ok){if(bytes.size()!=16)return c.reject("InvalidWorldId");for(std::size_t i=0;i<16;++i){if(bytes[i]<0||bytes[i]>255)return c.reject("InvalidWorldId");value[i]=static_cast<std::uint8_t>(bytes[i]);}}return c.status();}
