Outcome<GrowthTacticLessonCatalog> decode_growth_tactic_lesson_catalog(const V& v){try{unique(v);boundary::fields(v,{"version","definitions"},{},"growth_tactic_lessons");if(boundary::get_int(v,"version","")!=1)boundary::fail("UnsupportedTacticLessonVersion","");const auto& rows=boundary::object(boundary::field(v,"definitions",""),"definitions");if(rows.empty()||rows.size()>4096)boundary::fail("InvalidTacticLessonCatalog","");GrowthTacticLessonCatalog out;for(const auto& row:rows){const auto& value=row.second;boundary::fields(value,{"id","tactic_id","teacher_actor_id","dialogue_id","offer_node_id","recipient_wallet_id","duration","total_fee"},{},row.first);GrowthTacticLessonDefinition d;d.id=boundary::get_string(value,"id","");d.tactic_id=boundary::get_string(value,"tactic_id","");d.teacher_actor_id=boundary::get_string(value,"teacher_actor_id","");d.dialogue_id=boundary::get_string(value,"dialogue_id","");d.offer_node_id=boundary::get_string(value,"offer_node_id","");d.recipient_wallet_id=boundary::get_string(value,"recipient_wallet_id","");d.duration=boundary::get_int(value,"duration","");d.total_fee=boundary::get_int(value,"total_fee","");auto valid=validate_growth_tactic_lesson_definition_shape(d);if(!valid.ok)return {false,{},valid.error};if(row.first!=d.id||!out.definitions.insert(row.first,std::move(d)))boundary::fail("InvalidTacticLessonDefinition",row.first);}return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<GrowthTacticLessonState> decode_growth_tactic_lessons(const V& v){try{unique(v);boundary::fields(v,{"version","starts","credits","closures"},{},"growth_tactic_lessons");if(boundary::get_int(v,"version","")!=1)boundary::fail("UnsupportedTacticLessonVersion","");GrowthTacticLessonState out;
for(const auto& row:boundary::object(boundary::field(v,"starts",""),"starts"))if(!out.starts.insert(row.first,read_start(row.second)))boundary::fail("DuplicateTacticLessonRecord",row.first);
for(const auto& row:boundary::object(boundary::field(v,"credits",""),"credits"))if(!out.credits.insert(row.first,read_credit(row.second)))boundary::fail("DuplicateTacticLessonRecord",row.first);
for(const auto& row:boundary::object(boundary::field(v,"closures",""),"closures"))if(!out.closures.insert(row.first,read_closure(row.second)))boundary::fail("DuplicateTacticLessonRecord",row.first);
out.field_order=boundary::order(v);auto checked=validate_growth_tactic_lesson_shape(out);return checked.ok?Outcome<GrowthTacticLessonState>{true,std::move(out),{}}:Outcome<GrowthTacticLessonState>{false,{},checked.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_growth_tactic_lessons_fields(ProjectionWriter& w,const GrowthTacticLessonState& s){auto checked=validate_growth_tactic_lesson_shape(s);if(!checked.ok)return checked;w.field("version",Integer{1});w.object("starts",[&](auto& x){for(const auto& row:s.starts.rows())x.object(row.first,[&](auto& record){return emit_growth_tactic_lesson_start_fields(record,row.second);});return x.status();});w.object("credits",[&](auto& x){for(const auto& row:s.credits.rows())x.object(row.first,[&](auto& record){return emit_growth_tactic_lesson_credit_fields(record,row.second);});return x.status();});w.object("closures",[&](auto& x){for(const auto& row:s.closures.rows())x.object(row.first,[&](auto& record){return emit_growth_tactic_lesson_closure_fields(record,row.second);});return x.status();});return w.order_fields(s.field_order);}
BoundaryValue encode_growth_tactic_lessons(const GrowthTacticLessonState& s){return family_projection::encode([&](auto& w){return emit_growth_tactic_lessons_fields(w,s);});}
Status visit_growth_tactic_lessons_checkpoint(CodecVisitor& c,GrowthTacticLessonState& s){Integer version=1;c.field("version",version);if(version!=1)return c.reject("UnsupportedTacticLessonVersion");common_checkpoint::table(c,"starts",s.starts,[](CodecVisitor& q,GrowthTacticLessonStart& row){return visit(q,row);});common_checkpoint::table(c,"credits",s.credits,[](CodecVisitor& q,GrowthTacticLessonCredit& row){return visit(q,row);});common_checkpoint::table(c,"closures",s.closures,[](CodecVisitor& q,GrowthTacticLessonClosure& row){return visit(q,row);});common_checkpoint::strings(c,"field_order",s.field_order);if(!c.status().ok)return c.status();auto checked=validate_growth_tactic_lesson_shape(s);return checked.ok?c.status():c.reject(checked.error.original.code);}
